#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long powerMod(long long base, long long exponent) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k, l;
    cin >> n >> k >> l;

    vector<long long> factorial(n + 1, 1);
    for (int i = 1; i <= n; i++) {
        factorial[i] = (factorial[i - 1] * i) % mod;
    }

    vector<vector<long long>> dynamic(2 * n + 1, vector<long long>(2 * n + 2, 0));
    dynamic[0][0] = 1;

    for (int i = 1; i <= 2 * n; i++) {
        for (int j = 0; j <= min(i, n); j++) {
            if (j > 0) {
                dynamic[i][j] = (dynamic[i][j] + dynamic[i - 1][j - 1]) % mod;
            }
            dynamic[i][j] = (dynamic[i][j] + dynamic[i - 1][j + 1] * (j + 1) % mod) % mod;
        }
    }

    long long total = 0;
    for (int i = k; i <= 2 * n; i++) {
        for (int j = k; j <= n; j++) {
            total = (total + dynamic[i][j] * dynamic[2 * n - i][j] % mod * factorial[j] % mod) % mod;
        }
    }

    long long invA = powerMod(dynamic[2 * n][0], mod - 2);
    long long invB = powerMod(2 * n + 1, mod - 2);
    cout << (l * total % mod * invA % mod * invB % mod) << "\n";

    return 0;
}
